import Database from 'better-sqlite3'
import path from 'node:path'

const DB_PATH = path.join(process.cwd(), 'sqlite.db')

let db: Database.Database

function getDb(): Database.Database {
  if (!db) {
    db = new Database(DB_PATH)
    db.pragma('journal_mode = WAL')
    db.exec(`
      CREATE TABLE IF NOT EXISTS counter (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        value INTEGER NOT NULL DEFAULT 0
      )
    `)
    // Ensure the row exists
    const row = db.prepare('SELECT id FROM counter WHERE id = 1').get() as
      | { id: number }
      | undefined
    if (!row) {
      db.prepare('INSERT INTO counter (id, value) VALUES (1, 0)').run()
    }
  }
  return db
}

export function getCount(): number {
  const database = getDb()
  const row = database
    .prepare('SELECT value FROM counter WHERE id = 1')
    .get() as { value: number }
  return row.value
}

export function incrementCount(): number {
  const database = getDb()
  const result = database
    .prepare('UPDATE counter SET value = value + 1 WHERE id = 1 RETURNING value')
    .get() as { value: number }
  return result.value
}

import { createServerFn } from '@tanstack/react-start'
import { getCount, incrementCount } from '../db'

export const getCountServerFn = createServerFn({
  method: 'GET',
}).handler(async () => {
  return getCount()
})

export const incrementCountServerFn = createServerFn({
  method: 'POST',
}).handler(async () => {
  return incrementCount()
})

import { createFileRoute } from '@tanstack/react-router'
import { useState } from 'react'
import { getCountServerFn, incrementCountServerFn } from '../server-fns/counter'

export const Route = createFileRoute('/')({
  loader: async () => {
    const count = await getCountServerFn()
    return { count }
  },
  component: CounterPage,
})

function CounterPage() {
  const { count: initialCount } = Route.useLoaderData()
  const [count, setCount] = useState(initialCount)

  const handleIncrement = async () => {
    const newCount = await incrementCountServerFn()
    setCount(newCount)
  }

  return (
    <main className="flex min-h-screen flex-col items-center justify-center gap-6 p-8">
      <h1 className="text-3xl font-bold">Counter</h1>
      <p className="text-6xl font-mono" data-testid="count">
        {count}
      </p>
      <button
        data-testid="increment"
        onClick={handleIncrement}
        className="rounded-lg bg-blue-600 px-6 py-3 text-lg font-semibold text-white transition hover:bg-blue-700 active:scale-95"
      >
        Increment
      </button>
    </main>
  )
}

